+/** Per item between two days (inclusive): theoretical use from sales, actual use from consume movements, and their difference. */
+export function varianceReport(store, from, to) {
+  const theory = new Map();
+  const actual = new Map();
+  const add = (map, id, qty) => map.set(id, (map.get(id) ?? 0) + qty);
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const n of scaled(getRecipe(store, getDish(store, sale.dishId).recipeId), sale.qty)) add(theory, n.itemId, n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(actual, batch.itemId, m.qty);
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return [...new Set([...theory.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round(theory.get(itemId) ?? 0);
+      const a = round(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
